using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SelflessIgniteAction", menuName = "Data/Battle/Battle Actions/Sothis/SelflessIgnite Action")]
public class SelflessIgniteAction : TriggerEffectAction
{
	[Header("Selfless Ignite")]
	[SerializeField]
	private AfflictionDefaultEffectAction afflictionDefaultEffectAction;

	public AfflictionDefaultEffectAction AfflictionDefaultEffectAction => afflictionDefaultEffectAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (amount > 0)
		{
			afflictionDefaultEffectAction.CastTargetAmount(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject, amount, source);
		}
		DefaultCast(target, source);
	}
}
